import{c as e,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Auto-load 4 提案 byte 天花板評估 — 2026-06-27","description":"","frontmatter":{"date":"2026-06-27T00:00:00.000Z","status":"評估完成，待人工選路徑後實作","method":"逐提案 auto-load worthiness + byte 量測 + 下沉候選 + 分階段 eval-gated 計劃","proposals":["rewind-06-25","self-prompting-06-23","mcp-auth-06-22","loop-design-06-26"],"scope":"4 個 auto-load 待審提案 vs 19,000B 門檻","type":"evaluation-report / 實證計劃書"},"headers":[],"relativePath":"research/reports/2026-06-27-autoload-4proposal-byte-ceiling-eval.md","filePath":"research/reports/2026-06-27-autoload-4proposal-byte-ceiling-eval.md","lastUpdated":1785909234000}'),l={name:"research/reports/2026-06-27-autoload-4proposal-byte-ceiling-eval.md"};function d(s,t,n,i,c,p){return o(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="auto-load-4-提案-byte-天花板評估-—-2026-06-27" tabindex="-1">Auto-load 4 提案 byte 天花板評估 — 2026-06-27 <a class="header-anchor" href="#auto-load-4-提案-byte-天花板評估-—-2026-06-27" aria-label="Permalink to &quot;Auto-load 4 提案 byte 天花板評估 — 2026-06-27&quot;">​</a></h1><h2 id="_1-約束-量測-非估計" tabindex="-1">1. 約束（量測，非估計） <a class="header-anchor" href="#_1-約束-量測-非估計" aria-label="Permalink to &quot;1. 約束（量測，非估計）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLAUDE.md 1702 · core.md 9797 · context-management 1758 · output-discipline 1458</span></span>
<span class="line"><span>· subagent-strategy 3271 · README 1012  → total 18,998 / 19,000B（剩 2B）</span></span></code></pre></div><p>core.md §Framework Integrity 三段門檻：≤13,000 理想｜13,000–19,000 <strong>正當化區間（現況）</strong>｜&gt;19,000 觸發審視。當前已在正當化區間 → 任何新增須個別正當化；越過 19,000 須「同等級實證計劃書背書，<strong>不接受為塞單一新規則反推湊 byte</strong>」。並受「≤1 規則/cycle、≤50 行 diff」約束。</p><p>→ 4 提案天真全加 ≈ +640B → ~19,640B，<strong>同時違反 3 條</strong>（破 19,000 / 反推湊 byte / 一次 4 條）。security 兩項已落地是因 security-hygiene.md 為 on-demand 檔，不在六源預算內——此後路對這 4 項不存在。</p><h2 id="_2-逐提案-auto-load-worthiness-關鍵分析" tabindex="-1">2. 逐提案 auto-load worthiness（關鍵分析） <a class="header-anchor" href="#_2-逐提案-auto-load-worthiness-關鍵分析" aria-label="Permalink to &quot;2. 逐提案 auto-load worthiness（關鍵分析）&quot;">​</a></h2><p>判準（core.md）：「只寫無法從 repo 推導的行為契約；可推導資訊＝噪音」＋「移除後 Claude 在哪犯錯？」。<strong>不是每個研究發現都該進 auto-load。</strong></p><table tabindex="0"><thead><tr><th>提案</th><th>目標檔</th><th>防止的失敗模式</th><th>worthiness</th><th>裁定</th></tr></thead><tbody><tr><td><strong>loop-design 引用 (06-26)</strong></td><td>core.md</td><td>無——這是<strong>外部文獻 citation</strong>（《Loop Design》作 ground truth），不改 in-context 行為</td><td>★☆☆ 最弱</td><td><strong>不進 auto-load</strong> → 收入 <code>.claude/refs/harness-loop.md</code> 註腳即可；auto-load 放 citation = 噪音</td></tr><tr><td><strong>mcp-auth 隔離 (06-22)</strong></td><td>subagent-strategy</td><td>誤選整合方式（auth token 進 context）</td><td>★★☆</td><td><strong>折疊</strong>：已新增的 security-hygiene「Agent 部署 IPI 防護」涵蓋鄰近主題；auto-load 僅需 1 行指針（~80B）非整段 ~200B</td></tr><tr><td><strong>rewind 恢復 (06-25)</strong></td><td>context-management</td><td>誤以為 /clear 後不可恢復</td><td>★★☆</td><td><strong>就地擴句</strong>：檔內已 2 處提 /rewind；於既有行加 <code>（含 /clear 後恢復, v2.1.191+）</code> ~60B，非新增 2 行</td></tr><tr><td><strong>self-prompting (06-23)</strong></td><td>subagent-strategy</td><td>預設「人工提示每步」設計模式</td><td>★★★ 最強</td><td><strong>唯一值得完整進 auto-load</strong>（~200B）；行為契約、不可從 repo 推導</td></tr></tbody></table><p><strong>結論</strong>：真正需要 auto-load 空間的只有 self-prompting（~200B）；其餘 3 項降為「不進／指針／擴句」，總新增從 ~640B 壓到 <strong>~340B</strong>。</p><h2 id="_3-下沉候選-騰-340b-以維持-≤19-000" tabindex="-1">3. 下沉候選（騰 ~340B+ 以維持 ≤19,000） <a class="header-anchor" href="#_3-下沉候選-騰-340b-以維持-≤19-000" aria-label="Permalink to &quot;3. 下沉候選（騰 ~340B+ 以維持 ≤19,000）&quot;">​</a></h2><p>core.md 為最大宗（9,797B）。低頻 / 可推導 / 已有 ref 重複的下沉標的：</p><table tabindex="0"><thead><tr><th>候選</th><th>現 byte</th><th>下沉後</th><th>淨省</th><th>風險</th></tr></thead><tbody><tr><td><code>## 暫存 / Bash 慣例</code>（276B）細節 → <code>.claude/refs/</code>，auto-load 留 1 行指針</td><td>276</td><td>~90</td><td><strong>~186B</strong></td><td>低（操作慣例，低頻；hook 防呆仍在）</td></tr><tr><td>跨 section 括號內 citation／refs 指針重複（如「（見 …best-solution）」出現多次）</td><td>~分散</td><td>精簡</td><td><strong>~120–200B</strong></td><td>低（指針非鐵律句）</td></tr><tr><td><code>## The Loop（元迴圈）</code>（353B）與 CLAUDE.md 六階段敘述重疊段</td><td>353</td><td>~250</td><td><strong>~100B</strong></td><td>中（需確認不損 canonical 定義）</td></tr></tbody></table><p>下沉總潛力 ~400–480B &gt; 需求 ~340B → <strong>Path X（下沉後納入）數學可行</strong>。</p><h2 id="_4-實作計劃書-eval-gated-分階段" tabindex="-1">4. 實作計劃書（eval-gated，分階段） <a class="header-anchor" href="#_4-實作計劃書-eval-gated-分階段" aria-label="Permalink to &quot;4. 實作計劃書（eval-gated，分階段）&quot;">​</a></h2><p>core.md 要求變更附 <strong>Falsifiable Prediction + eval 條件</strong>，走 <code>/autoload-evolution</code> 閉環（≤1 規則/cycle、回歸 ≥5pp → git revert）。建議 4 個 cycle：</p><p><strong>Cycle 1（下沉騰空間，不加規則）</strong></p><ul><li>動作：暫存/Bash 慣例細節 + 重複 citation 下沉至 refs。</li><li>Falsifiable：下沉後 <code>wc -c</code> 六源 ≤ 18,650B（騰出 ≥350B headroom）。</li><li>eval：healthcheck FAIL=0；六階段 behavioral 全存活；下沉內容在 ref 可 grep 到。</li></ul><p><strong>Cycle 2（self-prompting → subagent-strategy）</strong></p><ul><li>Falsifiable：<code>grep -qE &#39;self-prompt|自我提示.*系統&#39; subagent-strategy.md</code> 通過；六源 ≤19,000。</li><li>eval：模擬 fan-out 任務，agent 不再預設逐步人工提示。</li></ul><p><strong>Cycle 3（mcp-auth 指針 + rewind 擴句）</strong></p><ul><li>Falsifiable：兩 grep 閘門通過（mcp-auth <code>auth.*isolat</code>；rewind 收緊為 <code>clear.*rewind|v2.1.191</code>，修原 false-positive grep）；六源 ≤19,000。</li></ul><p><strong>Cycle 4（loop-design → ref，非 auto-load）</strong></p><ul><li>動作：citation 寫入 <code>.claude/refs/harness-loop.md</code>；EVOLUTION-QUEUE 標 <code>applied(ref)</code> 非 auto-load。</li><li>Falsifiable：<code>grep -q &#39;Loop Design&#39; .claude/refs/harness-loop.md</code>；<strong>auto-load byte 不增</strong>。</li></ul><p>每 cycle 後量六源 byte + healthcheck，回歸 ≥5pp 即 <code>git revert</code> 該 cycle。</p><h2 id="_5-兩條路徑與建議" tabindex="-1">5. 兩條路徑與建議 <a class="header-anchor" href="#_5-兩條路徑與建議" aria-label="Permalink to &quot;5. 兩條路徑與建議&quot;">​</a></h2><ul><li><strong>Path X — 下沉後納入（建議）</strong>：依 §4 四 cycle，維持 ≤19,000，honor 全部框架門檻。最穩。</li><li><strong>Path Y — 上調 cap 至 ~19,500</strong>：core.md 允許「同等級實證計劃書背書」上調，但明文「不接受為塞單一新規則反推湊 byte」。為 4 條小規則上調 cap 正中此禁區 → <strong>不建議</strong>。</li></ul><p><strong>建議採 Path X</strong>。淨效果：auto-load 不增反可能微降（self-prompting 進、loop-design 不進、下沉 &gt; 新增），同時 3 條框架紀律全守。</p><h2 id="_6-待人工決策" tabindex="-1">6. 待人工決策 <a class="header-anchor" href="#_6-待人工決策" aria-label="Permalink to &quot;6. 待人工決策&quot;">​</a></h2><ol><li>採 Path X（下沉後納入）抑或調整提案取捨？</li><li>loop-design 確認「不進 auto-load、收 ref」可接受？</li><li>§3 下沉候選是否同意（特別是 The Loop 元迴圈段，動 canonical 定義須你點頭）？</li></ol><p>確認後我逐 cycle 走 <code>/autoload-evolution</code>，每 cycle 附 grep + byte + healthcheck 證據。</p><hr><h2 id="_7-pilot-review-終裁-2026-06-27-pilot-review-full-—-推翻部分-draft" tabindex="-1">7. Pilot Review 終裁（2026-06-27，/pilot-review full）— 推翻部分 draft <a class="header-anchor" href="#_7-pilot-review-終裁-2026-06-27-pilot-review-full-—-推翻部分-draft" aria-label="Permalink to &quot;7. Pilot Review 終裁（2026-06-27，/pilot-review full）— 推翻部分 draft&quot;">​</a></h2><p>四維評審（D1 haiku / D2 sonnet / D3 opus / D4 fable）對上述 draft 計劃書的修訂。主對話親跑復驗所有 load-bearing 宣稱。</p><p><strong>Verdict 鏈</strong>：D1 FLAG · D2 FLAG · D3 FLAG · D4 APPROVE_WITH_CONDITIONS（REVISE_THEN_PROCEED）。</p><p><strong>被推翻/修正的 draft 判斷（均已機械復驗）</strong>：</p><ol><li><strong>wc 命令不能下沉至 prompt-lifecycle.md</strong>（D4-CRITICAL，已驗）：prompt-lifecycle paths=<code>.claude/rules/**</code>,<code>CLAUDE.md</code>,<code>research/prompts/**</code>，純查詢 session 不載入 → 問「幾 byte」時取不到命令。§4 Cycle 1 的 (a) 取消，wc 留 core.md L78 原位。</li><li><strong>self-prompting 不該進 auto-load</strong>（D4-GAP，最重要）：「build self-prompting system」原則已由 Routines／multi-mode-agent／dynamic workflows 架構落地；grep 通過＝文字存在≠行為改變。§2 評 ★★★ 過高 → 降為 <strong>defer，待提行為改變證據</strong>。</li><li><strong>上調 cap 至 21,000B 拒絕</strong>（D4-ARBITRATE）：屬「架構論述」非「同等級實證計劃書」，違反 core.md「不接受反推湊 byte」。</li><li><strong>byte 估算需實測</strong>（D4）：實測 L4=224B、L17-19=347B、L78=334B；D3 的 ~243B 為估算。</li><li><strong>4 提案須分 4 獨立 cycle</strong>（D4-CRITICAL，已驗 SKILL「每 cycle ≤1 規則檔」）：不可批量。</li><li><strong>Bash 慣例不動</strong>（D1 主張，D2/D3/D4 同意，有 block-dangerous.sh hook 對應）。</li></ol><p><strong>D4 優先序裁定</strong>：<code>security（已 applied）&gt; rewind（功能性 ~100B）&gt; self-prompting（存疑 defer）&gt; loop-design（收 ref）&gt; byte 壓縮</code>。</p><p><strong>修訂後最終建議（取代 §4 Path X 4-cycle）</strong>：</p><ul><li>✅ 已落地：security ×2（tokenizer + lethal-trifecta，on-demand 不佔預算）。</li><li>✅ 可做（零風險）：loop-design → <code>.claude/refs/</code>（+0 auto-load）；採 D3「90 天門檻重審」治理（非上調 cap）。</li><li>⚠️ 選做：rewind 單 cycle（~100B，由 L17-19 語義壓縮騰空間；grep 收緊為 <code>clear.*rewind|v2.1.191</code>）。</li><li>❌ defer：self-prompting（無行為證據）、mcp-auth（低優先）、core.md 其餘壓縮、上調 cap。</li><li><strong>機會成本</strong>：byte 微調 ROI≈0；力氣優先放 P1 真實交付（Unicode sanitization hook、Omnigent 對照）。</li></ul><p><strong>狀態</strong>：待人工授權後執行（loop-design 收 ref + 門檻重審為預設；rewind cycle 選做）。</p>`,40)])])}const u=e(l,[["render",d]]);export{h as __pageData,u as default};
